from collections import Counter


class Solution:
    def everyWordOnce(self, s: str, words: List[str]) -> List[int]:
        L, w = len(words[0]), len(words)
        need = Counter(words)
        out = []
        for i in range(len(s) - w * L + 1):
            have = Counter(s[i + j * L:i + (j + 1) * L] for j in range(w))
            if have == need:
                out.append(i)
        return out

