class Solution {
    public List<Integer> everyWordOnce(String s, String[] words) {
        int L = words[0].length(), w = words.length;
        Map<String, Integer> need = new HashMap<>();
        for (String x : words) need.merge(x, 1, Integer::sum);
        List<Integer> out = new ArrayList<>();
        for (int i = 0; i + w * L <= s.length(); i++) {
            Map<String, Integer> have = new HashMap<>();
            int j = 0;
            for (; j < w; j++) {
                String chunk = s.substring(i + j * L, i + (j + 1) * L);
                if (have.merge(chunk, 1, Integer::sum) > need.getOrDefault(chunk, 0)) break;
            }
            if (j == w) out.add(i);
        }
        return out;
    }
}

