class Solution {
public:
    vector<int> everyWordOnce(string& s, vector<string>& words) {
        int L = words[0].size(), w = words.size();
        unordered_map<string, int> need;
        for (auto& x : words) need[x]++;
        vector<int> out;
        for (int i = 0; i + w * L <= (int) s.size(); i++) {
            unordered_map<string, int> have;
            int j = 0;
            for (; j < w; j++) {
                string chunk = s.substr(i + j * L, L);
                auto it = need.find(chunk);
                if (it == need.end() || ++have[chunk] > it->second) break;
            }
            if (j == w) out.push_back(i);
        }
        return out;
    }
};

