static int L_;

static int cmp_word(const void* a, const void* b) {
    return strcmp(*(char* const*) a, *(char* const*) b);
}

static int cmp_chunk(const void* key, const void* item) {
    return strncmp((const char*) key, *(char* const*) item, L_);
}

static int* chunk_ids(const char* s, int n, char** words, int w, int L, int** need, int* distinct) {
    char** uniq = malloc(w * sizeof(char*));
    memcpy(uniq, words, w * sizeof(char*));
    qsort(uniq, w, sizeof(char*), cmp_word);
    int d = 0;
    *need = calloc(w, sizeof(int));
    for (int i = 0; i < w; i++) {
        if (d == 0 || strcmp(uniq[d - 1], uniq[i]) != 0) uniq[d++] = uniq[i];
        (*need)[d - 1]++;
    }
    L_ = L;
    int* id = malloc((n + 1) * sizeof(int));
    for (int j = 0; j + L <= n; j++) {
        char** hit = bsearch(s + j, uniq, d, sizeof(char*), cmp_chunk);
        id[j] = hit ? (int) (hit - uniq) : -1;
    }
    free(uniq);
    *distinct = d;
    return id;
}

int* everyWordOnce(char* s, char** words, int wordsSize, int* returnSize) {
    int n = strlen(s), L = strlen(words[0]), w = wordsSize, d, count = 0;
    int* need;
    int* id = chunk_ids(s, n, words, w, L, &need, &d);
    int* have = calloc(d, sizeof(int));
    int* out = malloc((n + 1) * sizeof(int));
    for (int i = 0; i + w * L <= n; i++) {
        int j = 0;
        for (; j < w; j++) {
            int c = id[i + j * L];
            if (c < 0 || ++have[c] > need[c]) { if (c >= 0) have[c]--; break; }
        }
        for (int t = 0; t < j; t++) have[id[i + t * L]]--;
        if (j == w) out[count++] = i;
    }
    free(id); free(need); free(have);
    *returnSize = count;
    return out;
}

