class Solution:
    def everyWordOnce(self, s: str, words: List[str]) -> List[int]:
        L, w = len(words[0]), len(words)
        need = {}
        for x in words:
            need[x] = need.get(x, 0) + 1
        out = []
        for off in range(L):
            have, left, used = {}, off, 0
            for j in range(off, len(s) - L + 1, L):
                chunk = s[j:j + L]
                if chunk not in need:
                    have, left, used = {}, j + L, 0
                    continue
                have[chunk] = have.get(chunk, 0) + 1
                used += 1
                while have[chunk] > need[chunk]:
                    have[s[left:left + L]] -= 1
                    used -= 1
                    left += L
                if used == w:
                    out.append(left)
                    have[s[left:left + L]] -= 1
                    used -= 1
                    left += L
        return sorted(out)

