class Solution {
    public List<Integer> everyWordOnce(String s, String[] words) {
        int L = words[0].length(), w = words.length, n = s.length();
        Map<String, Integer> need = new HashMap<>();
        for (String x : words) need.merge(x, 1, Integer::sum);
        List<Integer> out = new ArrayList<>();
        for (int off = 0; off < L; off++) {
            Map<String, Integer> have = new HashMap<>();
            int left = off, used = 0;
            for (int j = off; j + L <= n; j += L) {
                String chunk = s.substring(j, j + L);
                if (!need.containsKey(chunk)) { have.clear(); used = 0; left = j + L; continue; }
                have.merge(chunk, 1, Integer::sum);
                used++;
                while (have.get(chunk) > need.get(chunk)) {
                    have.merge(s.substring(left, left + L), -1, Integer::sum);
                    used--;
                    left += L;
                }
                if (used == w) {
                    out.add(left);
                    have.merge(s.substring(left, left + L), -1, Integer::sum);
                    used--;
                    left += L;
                }
            }
        }
        Collections.sort(out);
        return out;
    }
}

