        int L = words[0].size(), w = words.size(), n = s.size();
        unordered_map<string, int> need;
        for (auto& x : words) need[x]++;
        vector<int> out;
        for (int off = 0; off < L; off++) {
            unordered_map<string, int> have;
            int left = off, used = 0;
            for (int j = off; j + L <= n; j += L) {
                string chunk = s.substr(j, L);
                if (!need.count(chunk)) { have.clear(); used = 0; left = j + L; continue; }
                have[chunk]++;
                used++;
                while (have[chunk] > need[chunk]) {
                    have[s.substr(left, L)]--;
                    used--;
                    left += L;
                }
                if (used == w) {
                    out.push_back(left);
                    have[s.substr(left, L)]--;
                    used--;
                    left += L;
                }
            }
        }
        sort(out.begin(), out.end());
        return out;
    }
};

