    L_ = L;
    int* id = malloc((n + 1) * sizeof(int));
    for (int j = 0; j + L <= n; j++) {
        char** hit = bsearch(s + j, uniq, d, sizeof(char*), cmp_chunk);
        id[j] = hit ? (int) (hit - uniq) : -1;
    }
    free(uniq);
    *distinct = d;
    return id;
