static int cmp_int(const void* a, const void* b) {
    return *(const int*) a - *(const int*) b;
}

int* everyWordOnce(char* s, char** words, int wordsSize, int* returnSize) {
    int n = strlen(s), L = strlen(words[0]), w = wordsSize, d, count = 0;
    int* need;
    int* id = chunk_ids(s, n, words, w, L, &need, &d);
    int* have = calloc(d, sizeof(int));
    int* out = malloc((n + 1) * sizeof(int));
    for (int off = 0; off < L; off++) {
        int left = off, used = 0;
        for (int j = off; j + L <= n; j += L) {
            int c = id[j];
            if (c < 0) {
                for (; left < j; left += L) have[id[left]]--;
                used = 0;
                left = j + L;
                continue;
            }
            have[c]++;
            used++;
            while (have[c] > need[c]) { have[id[left]]--; used--; left += L; }
            if (used == w) { out[count++] = left; have[id[left]]--; used--; left += L; }
        }
        for (; left + L <= n && used > 0; left += L, used--) have[id[left]]--;
    }
    qsort(out, count, sizeof(int), cmp_int);
    free(id); free(need); free(have);
    *returnSize = count;
    return out;
}
